import{_ as o,c as t,ae as i,o as r}from"./chunks/framework.Buicxtqr.js";const p=JSON.parse('{"title":"BuddyGenAI Dev Docs","description":"","frontmatter":{},"headers":[],"relativePath":"dev/README.md","filePath":"dev/README.md"}'),s={name:"dev/README.md"};function a(d,e,c,l,n,h){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="buddygenai-dev-docs" tabindex="-1">BuddyGenAI Dev Docs <a class="header-anchor" href="#buddygenai-dev-docs" aria-label="Permalink to &quot;BuddyGenAI Dev Docs&quot;">​</a></h1><p>This is the first installment of me documenting how this project is structured and works so that other developers can work on it.</p><div class="note custom-block github-alert"><p class="custom-block-title">I haven&#39;t actively worked with this codebase in a while, so I&#39;m partially writing this to strengthen my own understanding of things.</p><p></p></div><h2 id="other-pages" tabindex="-1">Other Pages <a class="header-anchor" href="#other-pages" aria-label="Permalink to &quot;Other Pages&quot;">​</a></h2><ul><li><a href="./database-info.html">Database Info</a></li><li><a href="./unifying-versions.html">Unifying BuddyGenAI Versions</a></li></ul><h2 id="source-code-file-structure" tabindex="-1">Source Code / File Structure <a class="header-anchor" href="#source-code-file-structure" aria-label="Permalink to &quot;Source Code / File Structure&quot;">​</a></h2><p>This project has the following in terms of files and directories, starting at the root:</p><ul><li><code>/.github/workflows/deploy.yml</code>: Builds and deploys new versions of the web app to GitHub Pages.</li><li><code>/assets/</code>: Static folder from which resources can be referenced with a URL such as <code>/assets/logo.png</code>.</li><li><code>/build/</code>: Directory used for Electron-Builder files. <ul><li><code>icon.{ico,png}</code>: The icon to be shown for this application in the Electron version.</li><li><code>license.txt</code>: Shown for the user to accept when installing the Electron version.</li></ul></li><li><code>/docs/</code>: The source for this docs site, made with Vitepress (<strong><em>to-do</em></strong>).</li><li><code>/electron/</code>: Source for the Electron version&#39;s backend / main process. <ul><li><code>background.ts</code>: Entrypoint for the Main process.</li><li><code>dynamicRenderer.ts</code>: Module which handles loading the web app in the Renderer window.</li></ul></li><li><code>/licenses/</code>: Directory containing LICENSE text files from the projects that we use.</li><li><code>/migrations/</code>: SQL files used to construct a fresh SQLite database (for use with Electron version).</li><li><code>/public/</code></li><li><code>/scripts/</code></li><li><code>/src/</code>: Source code for web app.</li><li><code>/app.vue</code>: The Vue entrypoint for the app.</li><li><code>/build.js</code>: Pain JS script to build Electron version.</li><li><code>/index.{html,ts}</code>: HTML &amp; JS (compiled) entrypoints for the web app.</li><li><code>/typed-router.d.ts</code>: File defining the file-based routes, generated and managed by <a href="https://github.com/posva/unplugin-vue-router" target="_blank" rel="noreferrer">unplugin-vue-router</a> during compilation, should be committed to the git repo.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>This is a link to the latest commit before I started removing unused code: <a href="https://github.com/parsehex/BuddyGenAI/tree/a35ce00bcb885b9cd026e55e85fad5b36976e4ef" target="_blank" rel="noreferrer">https://github.com/parsehex/BuddyGenAI/tree/a35ce00bcb885b9cd026e55e85fad5b36976e4ef</a></li></ul>',10)]))}const f=o(s,[["render",a]]);export{p as __pageData,f as default};
